# (id, topic, title, answer, source, reviewer_note)
MHM = "UNICEF/IMC Growing Healthy booklet 2015"
CSE = "REB/UNFPA CSE Reference Book 2018"
FP  = "WHO/JHU Family Planning Handbook 2022"
ADC = "WHO Adolescent Contraception 2017"
SRHR = "WHO Adolescent SRHR 2018"
HIV = "Rwanda HIV Guidelines 2022"
ITG = "UNESCO ITGSE"

KB = [
# ---------------- MENSTRUATION ----------------
("M-001","menstruation","What is a period",
 "A period (menstruation) is when blood and tissue leave your body through the vagina, usually for 2 to 7 days. It is a sign that you are growing up normally and that your body is healthy. All girls go through this change.",
 MHM,""),
("M-002","menstruation","When girls start their period",
 "Girls can start their period any time from about age 8 to 18. Most girls start between 10 and 14. Every body has its own timing. If you are worried about your own timing, a nurse can talk with you.",
 MHM,""),
("M-003","menstruation","How often periods come and irregular periods",
 "A period usually comes about every 28 days, but anything from 21 to 35 days can be normal. In the first year or two it can be irregular while your body adjusts. Stress, heavy exercise, poor eating or an emergency situation can also make periods irregular. If you have had sex and your period is late, pregnancy is possible, so think about a pregnancy test.",
 MHM+"; "+CSE,"Last sentence added from CSE book (missed period may mean pregnancy)."),
("M-004","menstruation","How long a period lasts",
 "Bleeding usually lasts 2 to 7 days, but it can be different for different girls. If bleeding is very heavy, for example soaking a pad every hour, or lasts much longer than 7 days, please see a health worker.",
 MHM,"Second sentence (heavy bleeding advice) is general practice, not from the booklet. Please confirm."),
("M-005","menstruation","Staying clean and bad smell during a period",
 "A bad smell comes from bacteria that grow when blood is warm and moist. Change your pad or cloth every 3 to 5 hours, or sooner if it is soaked. Wash your genital area with soap and water at least twice a day, wash your hands after using the toilet or changing your pad, and wipe from front to back. Do not use perfumes, herbs or ointments on your private parts.",
 MHM,""),
("M-006","menstruation","Period pain and cramps",
 "Pain in the lower back or stomach during a period is common. To feel better you can move and stretch, do some exercise, put a hot compress on the painful area or have a warm bath. Ibuprofen may help if you have it. If the pain is very strong or stops you from doing your normal activities, see a health worker.",
 MHM,"Last sentence is general practice, not from the booklet. Please confirm."),
("M-007","menstruation","Vaginal discharge",
 "Clear, cloudy white or yellowish discharge between periods is normal. Changes in your discharge, a new bad smell, itching or a burning feeling can be signs of infection. If you notice these, please see a health worker.",
 MHM,""),
("M-008","menstruation","Pads, leaks, disposal and washing cloths",
 "Use only clean and dry pads or cloths and keep a spare with you, especially at school. If blood leaks through your clothes, which happens to almost every girl, tie a jacket or sweater around your waist and change as soon as you can. Wrap used pads in paper or plastic and put them in a bin. Never throw them in the toilet. Wash reusable cloths with clean water and soap and dry them in the sun, which helps kill germs.",
 MHM,""),
("M-009","menstruation","Period myths",
 "You can bathe, swim and wash your hair during your period. Washing helps prevent infection. Eating sour or salty food or drinking cold drinks does not stop your period. You do not need to stop running or moving; movement may even ease cramps, but rest if your body asks for it. Menstrual blood is not dirty. Menstruation is a natural part of life.",
 MHM+"; "+CSE,""),
("M-010","menstruation","Tracking your period on a calendar",
 "Mark the first day of each period on a calendar, how many days it lasts and which days are heavy. After a few months you can predict when the next one will come. A cycle is usually 21 to 35 days, counted from the first day of one period to the first day of the next. Cycles can be irregular in the first years.",
 MHM,"Booklet says to count 21-35 days 'from the end of each period'. Standard practice counts from the first day. Please confirm wording."),
# ---------------- PUBERTY ----------------
("PU-001","puberty","What is puberty",
 "Puberty is the time when your body changes from a child's body to an adult's body. Your body, your feelings and your social life all change. It is normal and healthy. It does not start at the same age for everyone, and girls usually start earlier than boys.",
 CSE,""),
("PU-002","puberty","Body changes in girls and boys",
 "Both girls and boys grow taller, grow hair on the body, in the armpits and on the genitals, get oilier skin with pimples, sweat more and have bigger genitals. Girls also develop breasts, get wider hips and start their periods. Boys also get broader shoulders, more muscle, facial hair, a deeper voice, first ejaculation and wet dreams.",
 CSE,""),
("PU-003","puberty","Wet dreams and sudden erections",
 "A wet dream is when a boy ejaculates while he sleeps. Sudden erections are also common in teenage boys, even many times a day. Both are normal and harmless, and part of growing up. Erections go away by themselves. They do not mean a boy needs to have sex.",
 CSE,""),
("PU-004","puberty","Masturbation",
 "Many boys and girls masturbate during puberty or sometimes earlier. It does not cause physical or emotional harm, and it does not make you blind or weak. It is a private matter and should be done in private. If you feel worried or guilty about it, you can talk to a nurse or a trusted adult.",
 CSE+"; "+ITG,"Last sentence added for support. Please confirm tone."),
("PU-005","puberty","Mood changes and feelings in puberty",
 "During puberty your moods can change quickly, you may feel confused, worry about being normal, start to feel attraction to others and want to fit in with friends. All of this is common. Talking to a trusted friend, family member, teacher or nurse can help.",
 CSE+"; "+MHM,""),
("PU-006","puberty","Body hygiene in puberty",
 "In puberty your sweat and oil glands become more active, so wash your body and genital area often with soap and water. Wash your hands after using the toilet. Do not use perfumes, herbs or ointments on your private parts.",
 CSE+"; "+MHM,""),
("PU-007","puberty","Hymen and virginity myths",
 "The hymen can stretch or tear from sport, exercise or other activities, not only from sex. Some girls are born with a loose or very small hymen. So the hymen is not a reliable sign of virginity. Herbs or other things cannot restore virginity. A person can decide to wait for sex at any time, even after having had sex.",
 CSE,""),
# ---------------- CONTRACEPTION ----------------
("C-001","contraception","Pregnancy the first time and every time",
 "Yes. A girl can get pregnant the very first time she has sex, and every time she has sex without protection. Using a condom or another contraceptive method lowers the risk. A health worker can help you choose.",
 CSE+"; "+FP,""),
("C-002","contraception","What is contraception and what methods exist",
 "Contraception helps you prevent pregnancy and decide if and when to have children. Methods include condoms, pills, implants, injections, IUDs and emergency pills. Condoms are the only method that also protects against STIs, including HIV. A health worker can help you choose the method that fits your life.",
 ADC+"; "+FP,""),
("C-003","contraception","Are contraceptives safe for young people",
 "Yes. Young people can safely use any contraceptive method, and age alone is not a medical reason to refuse a method. Contraceptives are not only for married people. A health worker can explain what to expect, including common side effects.",
 FP+"; "+ADC+"; "+CSE,""),
("C-004","contraception","Male condoms",
 "Condoms are worn on the penis and block sperm and infections. They are the only method that protects against both pregnancy and STIs, including HIV. Used correctly every time, about 2 in 100 women get pregnant in a year; as commonly used, about 13 in 100. Use a new condom each time and talk about it with your partner before sex. Using two condoms at once does not protect more and can make them break.",
 FP+"; "+CSE,""),
("C-005","contraception","Birth control pills",
 "The combined pill is taken every day at the same time. As commonly used, about 7 in 100 women get pregnant in a year, and fewer than 1 in 100 if no pills are missed. Bleeding changes are common at first and not harmful. Pills do not protect against STIs. If you miss a pill, take it as soon as you remember and ask a health worker what else to do. Pills do not make you infertile; fertility returns when you stop.",
 FP+"; "+CSE,""),
("C-006","contraception","Implant",
 "The implant is a small rod, about the size of a matchstick, placed under the skin of the upper arm by a trained provider. It protects against pregnancy for 3 to 5 years, depending on the type, and is one of the most effective methods. It can be removed at any time and fertility returns right away. Bleeding changes are common and not harmful. It does not protect against STIs.",
 FP,""),
("C-007","contraception","Contraceptive injection",
 "The injection is given every 3 months (every 2 months for NET-EN). As commonly used, about 4 in 100 women get pregnant in a year. Bleeding changes are common and not harmful, and no one else can tell you are using it. It can take about 4 months longer to become pregnant after stopping. It does not protect against STIs.",
 FP+"; "+ADC,"WHO notes DMPA is category 2 for under 18s (benefits generally outweigh risks)."),
("C-008","contraception","IUD (coil)",
 "The copper IUD is a small device placed in the womb by a trained provider. It protects against pregnancy for up to 12 years and can be removed at any time. Periods may become heavier with more cramps in the first 3 to 6 months. It does not protect against STIs. IUDs can come out more often in women who have never given birth, so check with a health worker.",
 FP,""),
("C-009","contraception","Emergency contraceptive pills",
 "Emergency pills can help prevent pregnancy after sex without protection, a broken condom or forced sex. Take them as soon as possible, ideally within 3 days. They can still help up to 5 days after. They do not end an existing pregnancy and do not protect against STIs. They are safe to use, even more than once, but a regular method works better. A copper IUD can also be used for emergency contraception. If your period is more than 7 days late afterwards, take a pregnancy test.",
 FP+"; "+HIV,""),
("C-010","contraception","Contraception myths",
 "Contraceptives are not only for married people. Pills do not make you infertile. Washing the vagina with Coca-Cola or Sprite after sex does not prevent pregnancy. Using two condoms does not protect more. The days between periods are not always safe, especially when periods are irregular.",
 CSE,""),
("C-011","contraception","Withdrawal and counting days",
 "Withdrawal (pulling out) is one of the least effective methods: about 20 in 100 women get pregnant in a year as commonly used. Counting days is also unreliable, especially when periods are irregular, as they often are in teenagers. A condom or another method protects better.",
 FP+"; "+CSE,""),
("C-012","contraception","Permission and privacy for contraception",
 "WHO recommends that young people can get contraceptive information and services without needing a parent or guardian to approve, and with privacy and respect. Rwanda's CSE book states that adolescents have a right to information and services. Ask your health center about its rules and how it keeps your information private.",
 ADC+"; "+FP+"; "+CSE,"Please confirm current Rwandan rules for minors accessing contraception."),
# ---------------- PREGNANCY ----------------
("PR-001","pregnancy","Signs of pregnancy",
 "A missed period is a common first sign of pregnancy. Some people also feel sick, have tender breasts or feel very tired. A late period can have other causes, such as stress, so only a pregnancy test can tell you for sure.",
 CSE,"Signs other than missed period are general knowledge, not from the uploaded documents."),
("PR-002","pregnancy","How to know if you are pregnant",
 "A pregnancy test can tell you. You can get one at a health center. If you took emergency pills and your period is more than 7 days late, take a pregnancy test. If it is positive, go to a health center for antenatal care as early as possible.",
 FP,""),
("PR-003","pregnancy","When can a girl get pregnant",
 "A girl can get pregnant any time she has sex without protection, even the first time. The most fertile time is around the middle of the cycle, but periods in teenagers can be very irregular, so no day is reliably safe. A condom or another method gives better protection.",
 CSE,""),
("PR-004","pregnancy","Risks of teenage pregnancy",
 "Pregnancy at a young age brings higher health risks for the girl and the baby, and can affect her education and future work. Going for antenatal care early, eating well and having skilled care at birth reduce the risks. Contraception and staying in school help prevent early pregnancy.",
 ADC+"; "+SRHR,"Second sentence (antenatal care advice) is general practice. Please confirm."),
("PR-005","pregnancy","What to do if you are pregnant",
 "Go to a health center as early as you can for antenatal care. You will be offered tests, including HIV and syphilis, which protect you and your baby. Try to talk to an adult you trust. You have a right to respectful care without being judged.",
 HIV+"; "+SRHR,""),
("PR-006","pregnancy","Worried about pregnancy after sex without protection",
 "Pregnancy is possible after sex without protection. Emergency contraceptive pills can lower the risk if taken as soon as possible, ideally within 3 days and up to 5 days. Go to a health center or pharmacy soon. If your period is more than 7 days late afterwards, take a pregnancy test.",
 FP,""),
# ---------------- STIs ----------------
("S-001","stis","What are STIs",
 "STIs are infections that pass from person to person through sexual contact. Anyone who has had sex can get one. Many STIs have no symptoms, especially in girls, so a person can have one without knowing. Testing and treatment protect you and your partner.",
 CSE,""),
("S-002","stis","Signs of an STI",
 "Possible signs are a change in discharge, a new bad smell, itching, burning when passing urine, or sores. But many STIs show no signs at all. If you have had sex without a condom or you notice any of these, please get tested at a health center.",
 MHM+"; "+CSE,"Burning with urine and sores are general knowledge; please confirm list."),
("S-003","stis","Can STIs be cured",
 "Many STIs can be treated and cured with the right medicine, and early treatment prevents damage to your body. Some, such as HIV and herpes, cannot be cured but can be managed. Go to a health center for testing and treatment.",
 CSE+"; "+HIV,""),
("S-004","stis","Getting tested and treated for an STI",
 "You can get tested and treated at a health center. Treatment is usually very effective. Health workers should treat you with respect and keep your information private. Do not use herbs or ointments on your private parts.",
 CSE+"; "+ADC+"; "+MHM,"Please confirm rules on parental permission for under-age clients."),
("S-005","stis","Condoms and STI protection",
 "Condoms reduce the risk of many STIs when used correctly every time you have sex. They protect best against STIs spread by discharge, such as HIV, gonorrhea and chlamydia, and also help against herpes and HPV. Other methods such as pills, implants, injections and emergency pills do not protect against STIs.",
 FP,""),
("S-006","stis","Can you get an STI from toilets or swimming",
 "STIs are mainly spread through sexual contact with an infected person. You cannot get an STI from toilet seats, swimming pools, sharing food, hugging or other normal contact.",
 CSE+"; "+HIV,"CSE says STIs occur through sexual contact; some infections can also pass by blood or from mother to baby. Wording says mainly. Please confirm."),
("S-007","stis","HPV vaccine",
 "The HPV vaccine protects against the virus that can cause cervical cancer. Ask your school nurse or health center about the vaccine and who can get it.",
 SRHR,"Please add Rwanda's national HPV vaccine schedule."),
# ---------------- HIV ----------------
("H-001","hiv","What is HIV and AIDS",
 "HIV is a virus that weakens the body's defense against disease. AIDS is the late stage of untreated HIV infection. With treatment, people living with HIV can stay healthy and live long lives.",
 CSE+"; "+HIV,""),
("H-002","hiv","How HIV is passed on and how it is not",
 "HIV passes through unprotected sex, contact with infected blood and from mother to baby. It is not passed by touching, hugging, sneezing, sharing food, cups or toilets, swimming pools, mosquito bites, or tears and sweat.",
 CSE,""),
("H-003","hiv","How to prevent HIV",
 "Use condoms correctly every time you have sex; they prevent 80 to 95 percent of HIV transmission that would otherwise occur. Get tested, get STIs treated, and ask a health worker about PrEP (daily pills before exposure) and PEP (pills after exposure). Never share needles or blades.",
 FP+"; "+HIV,"Needles/blades sentence is general knowledge."),
("H-004","hiv","HIV testing",
 "Testing is voluntary and private. In Rwanda, people aged 12 and above can agree to a test themselves, and for children aged 10 to 11 a parent or guardian agrees. A self-test kit is for people aged 16 and above and is sold at health facilities and pharmacies. A positive self-test must be confirmed by a health worker.",
 HIV,""),
("H-005","hiv","HIV window period",
 "After infection, it can take from 2 weeks up to 3 to 6 months for a test to show positive. This is the window period. If you had a recent risk and tested negative, test again later. A negative self-test does not rule out HIV after recent exposure.",
 CSE+"; "+HIV,""),
("H-006","hiv","PrEP",
 "PrEP is a daily pill that HIV-negative people at higher risk can take to prevent HIV. It is voluntary. You must test negative first and be tested again every 3 months. It reaches full protection after 7 daily doses. You should still use condoms for other protection. Ask a health worker if PrEP is right for you.",
 HIV,""),
("H-007","hiv","PEP after possible exposure",
 "PEP is a 28-day course of HIV medicine that lowers the chance of infection after possible exposure, for example after rape or a condom failing with a partner living with HIV. Start it as soon as possible, ideally within 72 hours. Go to a health facility right away.",
 HIV,""),
("H-008","hiv","Treatment and living with HIV",
 "Everyone with HIV can start treatment (ART) on the same day as diagnosis. Taking medicine every day brings the virus to undetectable levels. Undetectable means untransmittable (U=U): the virus cannot pass to a sexual partner. Treatment is not a cure, so continue it for life, with support from a health worker.",
 HIV,""),
("H-009","hiv","HIV and pregnancy",
 "Pregnant women are offered an HIV test at antenatal care. If a mother is living with HIV, treatment and follow-up for the mother and baby greatly lower the chance of passing HIV to the baby. Go to antenatal care early.",
 HIV,"Please confirm wording of PMTCT statement against national PMTCT chapter."),
("H-010","hiv","Contraception for people living with HIV or at risk",
 "All family planning methods are safe for people at high risk of HIV or living with HIV, except spermicides containing nonoxynol-9. Condoms are still important to prevent HIV and other STIs. A health worker can help you choose a method that works with your HIV medicine.",
 FP+"; "+ADC,""),
# ---------------- RELATIONSHIPS ----------------
("R-001","relationships","What is a healthy relationship",
 "In a healthy relationship both people feel safe, respected and equal. You can say no without fear, talk honestly and make your own choices. Love is not control, threats or violence. If you feel afraid or controlled, talk to someone you trust.",
 ITG+"; "+CSE,"Please check wording against ITGSE learning objectives."),
("R-002","relationships","Pressure to have sex",
 "You have the right to decide about your own body, and nobody should pressure you into sex. It is okay to say no or to wait. You can say, \"I am not ready,\" or \"If you respect me, you will wait.\" Talk with a trusted adult or a health worker if the pressure continues.",
 FP+"; "+ITG,""),
("R-003","relationships","Am I ready for sex",
 "Only you can decide, and there is no rush. Think about whether you feel ready, safe and free from pressure, and whether you can protect yourself with condoms or another method. Waiting is a valid choice. You can talk to a nurse or an adult you trust.",
 ITG+"; "+CSE,""),
("R-004","relationships","Talking to a partner about condoms",
 "Talk about condoms before sex, when you are calm. You can say, \"I want us both to be safe.\" Talking before sex makes it more likely that a condom will be used. If your partner refuses, you can say no to sex. A health worker can help you practise what to say.",
 FP,""),
("R-005","relationships","Who can I talk to about these questions",
 "It is okay to want to know more and to ask for help. You can talk to a trusted teacher, friend, family member or a nurse at a health center. Health workers should not judge you and should keep your information private.",
 MHM+"; "+FP,""),
("R-006","relationships","Gender, equality and decisions",
 "Girls and women have the right to make their own decisions about sex and contraception, and boys and men share responsibility for the results of their actions. Respect and equality make relationships safer and healthier.",
 FP,""),
# ---------------- CONSENT AND SAFETY ----------------
("CS-001","consent_safety","What is consent",
 "Consent means that a person freely says yes to sex and can change their mind at any time. Sex needs agreement from both people each time. Silence, fear or being drunk or drugged is not consent. Anyone can say no.",
 CSE,""),
("CS-002","consent_safety","Sex with a person under 18",
 "In Rwanda, sex with a person under 18 is rape (statutory rape) even if the young person says yes. This protects children. If an adult is pursuing you or a friend, tell a trusted adult or call the child helpline on 116.",
 CSE,"Please confirm with legal advisor the current Rwandan law on age of consent."),
("CS-003","consent_safety","Bad touch and what to do",
 "No one has the right to touch you in a way that feels wrong, scary or secret. It is never your fault. Say no if you can, get away to a safe place and tell an adult you trust. You can call 116 (child helpline, free) for help.",
 ITG,""),
("CS-004","consent_safety","What to do after rape or sexual assault",
 "It was not your fault. Go as soon as you can to a health facility or an Isange One Stop Centre (call 3029). Care is free. If you go within 72 hours you can be given medicine to lower the chance of HIV (PEP) and emergency pills to prevent pregnancy. You can also be tested and get support. You can call 3512 for help. You do not have to report to the police to get health care.",
 HIV+"; RBC website","RBC page states services are free in district hospitals. Please confirm 'free' at Isange centres and 'no police report needed'."),
("CS-005","consent_safety","Sexual harassment",
 "Touching someone's body or making sexual comments without permission is sexual harassment. It is not okay, whoever does it. You can tell a trusted adult, a teacher or the police on 3512.",
 CSE,""),
("CS-006","consent_safety","Marriage does not mean consent to sex",
 "Agreeing to marry does not mean agreeing to sex. Everyone has the right to say yes or no each time. Forced sex inside marriage is still violence.",
 CSE,"Please confirm legal wording."),
("CS-007","consent_safety","Privacy and confidentiality",
 "Health workers should respect your privacy. Young people have a right to private, respectful care. This tool does not ask your name and does not save your questions.",
 SRHR+"; "+FP,"Confirm that the platform design actually stores no questions before launch."),
("CS-008","consent_safety","Where to get help and services",
 "You can go to your nearest health center or health post, or ask a community health worker. You can also call 114 (RBC free health line). For abuse, call 3512 (gender-based violence), 116 (child abuse) or 3029 (Isange One Stop Centre). For an emergency, call 112.",
 "RBC website; Rwanda National Police; RIB","Numbers checked on RBC and RIB websites in Oct 2026. Please verify before launch."),
]
